.card {
    padding: 12px 14px;
    border: 1px solid #e6e9ef;
    border-radius: 12px;
    background: #fff
}
.hw-card {
  padding: 12px;
  font-family: Roboto, system-ui, -apple-system, Segoe UI, Arial, sans-serif;
}
.hw-header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  margin-bottom: 10px;
}
.hw-title {
  font-weight: 600;
  font-size: 16px;
  color: rgba(0,0,0,.87);
}
.hw-time {
  font-size: 12px;
  color: rgba(0,0,0,.54);
}

/* 4 tiles (modules) */
.hw-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0,1fr));
  gap: 10px;
}
.hw-tile {
  border: 1px solid rgba(0,0,0,.12);
  border-radius: 10px;
  background: #fff;
  padding: 10px;
}
.hw-mod {
  font-weight: 600;
  margin-bottom: 4px;
}
.hw-status {
  display: inline-block;
  padding: 2px 8px;
  border-radius: 999px;
  font-size: 12px;
  margin-bottom: 6px;
  background: rgba(46,204,113,.15);
  color: #2e8b57;
}
.hw-status.bad {
  background: rgba(214,40,40,.15);
  color: #a61d24;
}

.hw-kpi { font-size: 13px; margin-bottom: 6px; color: rgba(0,0,0,.76); }
.hw-last .k { font-size: 11px; color: rgba(0,0,0,.54); }
.hw-last .v { font-size: 13px; font-weight: 600; color: rgba(0,0,0,.87); }

.hw-msg {
  margin-top: 6px;
  font-size: 12px;
  color: rgba(0,0,0,.76);
  word-break: break-word;
  white-space: normal;
  min-height: 2.2em;
}

