/* ATM Details — Hardware Faults (24h) — CE-safe (last time from faults-24h-xxx) */
self.onInit = function () {
  var root = self.ctx.$container[0];
  var elTime = root.querySelector('#hw24-time');

  var DEBUG = true;
  function log(m,o){ if(DEBUG) try{console.log('[hw24]', m, o||'');}catch(e){} }

  // Modules & their 24h count keys
  var MAP = {
    CARD_READER: 'faults-24h-card-reader',
    DISPENSER:   'faults-24h-dispenser',
    PRINTER:     'faults-24h-printer',
    EPP:         'faults-24h-epp'
  };
  var MODULES = Object.keys(MAP);

  function fmt(ts) {
    if (ts == null) return '—';
    try { return new Date(ts).toISOString().replace('T',' ').slice(0,19); }
    catch(_){ return String(ts); }
  }

  // Robust extractor for last point from TB series (timeseries or latest)
  function lastPoint(series) {
    var d = series && series.data ? series.data : [];
    if (!d.length) return null;
    var p = d[d.length - 1];
    // Handle array form [ts, val, ...] and object form {ts, value}
    var ts = Array.isArray(p) ? p[0] : (p && p.ts);
    var val = Array.isArray(p) ? p[1] : (p && (p.value !== undefined ? p.value : p.v));
    return { ts: ts, val: val, raw: p };
  }

  // Extract first non-empty string from TB shapes (incl. pt[2])
  function findFirstString(x, depth) {
    if (depth > 3) return '';
    if (typeof x === 'string' && x.trim() !== '') return x;
    if (x == null) return '';
    if (Array.isArray(x)) {
      for (var i=0;i<x.length;i++){ var s = findFirstString(x[i], depth+1); if (s) return s; }
      return '';
    }
    if (typeof x === 'object') {
      var pref = ['message','msg','text','value','v','raw','str','strValue','stringValue','payload','label'];
      for (var p=0;p<pref.length;p++){ var k = pref[p]; if (typeof x[k] === 'string' && x[k].trim() !== '') return x[k]; }
      for (var key in x){ if (!Object.prototype.hasOwnProperty.call(x,key)) continue; var s2 = findFirstString(x[key], depth+1); if (s2) return s2; }
      return '';
    }
    return '';
  }
  function coerceText(val, pt) {
    if (typeof val === 'string' && val.trim() !== '') return val;
    if (val && typeof val === 'object') { var s1 = findFirstString(val, 0); if (s1) return s1; try { return JSON.stringify(val); } catch(_){ } }
    if (pt && Array.isArray(pt) && pt.length > 2) { var s2 = findFirstString(pt[2], 0); if (s2) return s2; }
    if (pt) { var s3 = findFirstString(pt, 0); if (s3) return s3; }
    return String(val == null ? '' : val);
  }

  // Identify module from a log-event text
  var MOD_PATTERNS = [
    { mod: 'DISPENSER',   re: /(dispens(er|er[_\s-]*unit)?|cash[_\s-]*handler|cdu|cassette)/i },
    { mod: 'CARD_READER', re: /(card[_\s-]*reader|cardreader|reader|icc|magstripe|dip|motor[_\s-]*card|retained[_\s-]*card)/i },
    { mod: 'PRINTER',     re: /(printer|receipt[_\s-]*printer|journal[_\s-]*printer|ej[_\s-]*printer)/i },
    { mod: 'EPP',         re: /\b(epp|encrypt(ed)?\s*pin\s*pad|pinpad|pin[_\s-]*pad)\b/i }
  ];
  function detectModule(text) {
    var s = String(text || '');
    for (var i=0;i<MOD_PATTERNS.length;i++) {
      if (MOD_PATTERNS[i].re.test(s)) return MOD_PATTERNS[i].mod;
    }
    var u = s.toUpperCase();
    if (u.includes('DISPENSER') || u.includes('CDU')) return 'DISPENSER';
    if (u.includes('CARD_READER') || u.includes('CARDREADER') || u.includes('READER')) return 'CARD_READER';
    if (u.includes('PRINTER') || u.includes('RECEIPT') || u.includes('JOURNAL')) return 'PRINTER';
    if (u.includes('EPP') || u.includes('PINPAD')) return 'EPP';
    return null;
  }

  function setTile(mod, count, lastTsFromCount, lastRelatedLog) {
    var id = mod;
    var st  = root.querySelector('#st-'  + id);
    var ct  = root.querySelector('#ct-'  + id);
    var ts  = root.querySelector('#ts-'  + id);
    var msg = root.querySelector('#msg-' + id);

    if (!st || !ct || !ts || !msg) return;

    // Count/status from faults-24h-xxx (numeric)
    var n = Number(count);
    if (!isFinite(n)) n = 0;
    ct.textContent = String(n);
    if (n > 0) { st.textContent = 'Fault'; st.classList.add('bad'); }
    else       { st.textContent = 'OK';    st.classList.remove('bad'); }

    // Time from the last update of faults-24h-xxx (not from logs)
    ts.textContent = lastTsFromCount ? fmt(lastTsFromCount) : '—';

    // Last related message (best effort from log-event)
    msg.textContent = (lastRelatedLog && lastRelatedLog.trim()) ? lastRelatedLog : '—';
  }

  function render() {
    var ds = self.ctx.data || [];

    // Accumulators
    var countByMod = { CARD_READER:0, DISPENSER:0, PRINTER:0, EPP:0 };
    var tsByMod    = { CARD_READER:null, DISPENSER:null, PRINTER:null, EPP:null }; // from faults-24h-xxx
    var lastLogByMod = { CARD_READER:null, DISPENSER:null, PRINTER:null, EPP:null }; // {ts,msg} from log-event

    // 1) Walk all series once
    for (var i=0;i<ds.length;i++) {
      var s = ds[i];
      if (!s || !s.dataKey) continue;

      var key = String(s.dataKey.name || s.dataKey.label || '');

      // A) Handle the numeric counts
      for (var m of MODULES) {
        if (key === MAP[m]) {
          var lp = lastPoint(s);
          if (lp) {
            var n = Number(lp.val);
            if (!isFinite(n)) n = 0;
            countByMod[m] = n;
            tsByMod[m] = lp.ts || tsByMod[m]; // prefer last point ts when present
            if (DEBUG && i < 6) log('count series', {mod:m, ts: lp.ts, val: n, raw: lp.raw});
          }
        }
      }

      // B) Scan log-event for “last related message” per module (best effort)
      if (key === 'log-event') {
        var series = s.data || [];
        for (var j=0;j<series.length;j++) {
          var pt = series[j];
          var ts = Array.isArray(pt) ? pt[0] : (pt && pt.ts);
          var val = Array.isArray(pt) ? pt[1] : (pt && (pt.value !== undefined ? pt.value : pt.v));

          // Skip bucket placeholders like [ts,0,[start,end]]
          if ((val === 0 || val === '0' || val == null) && Array.isArray(pt) && Array.isArray(pt[2])) {
            if (DEBUG && j < 2) log('skip bucket placeholder', pt);
            continue;
          }
          var text = coerceText(val, pt);
          if (!text || text === '0') continue;

          var mod = detectModule(text);
          if (!mod || !lastLogByMod.hasOwnProperty(mod)) continue;

          if (!lastLogByMod[mod] || ts > lastLogByMod[mod].ts) {
            lastLogByMod[mod] = { ts: ts, msg: text };
          }
        }
      }
    }

    // 2) Header time = latest of the four faults-24h-* timestamps
    var headerTs = null;
    for (var m of MODULES) {
      if (tsByMod[m] != null) headerTs = (headerTs == null || tsByMod[m] > headerTs) ? tsByMod[m] : headerTs;
    }
    elTime.textContent = headerTs ? ('Last update: ' + fmt(headerTs)) : 'No updates in window';

    // 3) Paint tiles (time from counts; message from logs)
    for (var m of MODULES) {
      var lastLog = lastLogByMod[m] ? lastLogByMod[m].msg : '';
      setTile(m, countByMod[m], tsByMod[m], lastLog);
    }
  }

  render();
  self.onDataUpdated = render;
};

